export type EmptyWorkspaceViewProps = {
  onNewTerminal: () => void;
  onNewBrowserTab: () => void;
};

export function EmptyWorkspaceView({ onNewTerminal, onNewBrowserTab }: EmptyWorkspaceViewProps) {
  return (
    <div
      data-testid="empty-workspace-view"
      className="flex h-full flex-1 flex-col items-center justify-center gap-4 bg-background"
    >
      <div className="flex flex-col items-center gap-1 text-center">
        <p className="text-sm font-medium text-muted-foreground">No open tabs</p>
        <p className="text-xs text-muted-foreground/70">Open a terminal or browser tab to get started.</p>
      </div>
      <div className="flex items-center gap-2">
        <button
          type="button"
          onClick={onNewTerminal}
          className="flex items-center gap-1.5 rounded-md bg-accent px-3 py-1.5 text-xs font-medium text-foreground hover:bg-accent/80 transition-colors"
        >
          <Terminal className="size-3.5" />
          <span>New Terminal</span>
        </button>
        <button
          type="button"
          onClick={onNewBrowserTab}
          className="flex items-center gap-1.5 rounded-md border border-border px-3 py-1.5 text-xs font-medium text-muted-foreground hover:bg-accent hover:text-foreground transition-colors"
        >
          <Globe className="size-3.5" />
          <span>New Browser Tab</span>
        </button>
      </div>
    </div>
  );
}

import { cleanup, fireEvent, render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

import { EmptyWorkspaceView } from "./EmptyWorkspaceView";

afterEach(cleanup);

describe("EmptyWorkspaceView", () => {
  it("renders empty state message, secondary hint, and action buttons", () => {
    const onNewTerminal = vi.fn();
    const onNewBrowserTab = vi.fn();

    render(
      <EmptyWorkspaceView
        onNewTerminal={onNewTerminal}
        onNewBrowserTab={onNewBrowserTab}
      />,
    );

    expect(screen.getByTestId("empty-workspace-view")).toBeInTheDocument();
    expect(screen.getByText("No open tabs")).toBeInTheDocument();
    expect(
      screen.getByText("Open a terminal or browser tab to get started."),
    ).toBeInTheDocument();
    expect(
      screen.getByRole("button", { name: /New Terminal/i }),
    ).toBeInTheDocument();
    expect(
      screen.getByRole("button", { name: /New Browser Tab/i }),
    ).toBeInTheDocument();
  });

  it("calls onNewTerminal when New Terminal button is clicked", () => {
    const onNewTerminal = vi.fn();
    const onNewBrowserTab = vi.fn();

